INSERT INTO bizplan.sections (position, title, body_md) VALUES
(1,  'Executive Summary',     'High-level overview of the business opportunity, value proposition, and key objectives.'),
(2,  'Company Overview',      'Legal structure, ownership, location, and company history/background.'),
(3,  'Mission & Vision',      'Core mission statement, long-term vision, and guiding values.'),
(4,  'Market Analysis',       'Target market definition, size (TAM/SAM/SOM), trends, and customer segments.'),
(5,  'Competitive Analysis',  'Key competitors, competitive advantages, differentiation strategy, and market positioning.'),
(6,  'Products & Services',   'What we sell or deliver, key features, development roadmap, and intellectual property.'),
(7,  'Revenue Model',         'How we make money — pricing strategy, revenue streams, and unit economics.'),
(8,  'Marketing Strategy',    'Go-to-market plan, channels, customer acquisition, branding, and partnerships.'),
(9,  'Operations Plan',       'Day-to-day operations, supply chain, technology stack, and key processes.'),
(10, 'Team & Staffing',       'Founding team, key roles, hiring plan, advisory board, and equity/compensation structure.'),
(11, 'Financial Projections', 'Revenue forecasts, cost structure, cash flow, break-even analysis, and funding requirements.'),
(12, 'Risk Analysis',         'Key risks, mitigation strategies, contingency plans, and regulatory/compliance considerations.'),
(13, 'Timeline & Milestones', 'Key milestones, launch timeline, growth targets, and decision gates.');
